  /** Compute Entrypoint Contract
    *
    * guarantee REQUEST_RESULT_DERIVATION
    * @param api_resolutionIn incoming data port
    * @param api_pilotStatusOut outgoing data port
    */
  @strictpure def compute_spec_REQUEST_RESULT_DERIVATION_guarantee(
      api_resolutionIn: Drone_Lifecycle_Energy_Governor.LifecycleResolution,
      api_pilotStatusOut: Drone_Lifecycle_Energy_Governor.PilotStatus): B =
    !(api_resolutionIn.requestPresent) &
      api_pilotStatusOut.requestResult == RequestResult.NONE |
      api_resolutionIn.requestPresent & api_resolutionIn.requestCausedTransition &
        api_pilotStatusOut.requestResult == RequestResult.ACCEPTED |
      api_resolutionIn.requestPresent & !(api_resolutionIn.requestCausedTransition) &
        api_resolutionIn.requestDefeatedByPriority &
        api_pilotStatusOut.requestResult == RequestResult.PREEMPTED |
      api_resolutionIn.requestPresent & !(api_resolutionIn.requestCausedTransition) &
        !(api_resolutionIn.requestDefeatedByPriority) &
        api_pilotStatusOut.requestResult == RequestResult.REJECTED

  /** Compute Entrypoint Contract
    *
    * guarantee BATTERY_NOTICE_DERIVATION
    * @param api_batteryIn incoming data port
    * @param api_pilotStatusOut outgoing data port
    */
  @strictpure def compute_spec_BATTERY_NOTICE_DERIVATION_guarantee(
      api_batteryIn: Drone_Lifecycle_Energy_Governor.BatteryStateFacts,
      api_pilotStatusOut: Drone_Lifecycle_Energy_Governor.PilotStatus): B =
    api_batteryIn.confidence != BatteryConfidence.TRUSTED &
      api_pilotStatusOut.batteryNotice == BatteryNotice.UNTRUSTED |
      api_batteryIn.confidence == BatteryConfidence.TRUSTED &
        (api_batteryIn.band == BatteryBand.MEDIUM |
          api_batteryIn.band == BatteryBand.FULL) &
        api_pilotStatusOut.batteryNotice == BatteryNotice.CLEAR |
      api_batteryIn.confidence == BatteryConfidence.TRUSTED &
        api_batteryIn.band == BatteryBand.LOW &
        api_pilotStatusOut.batteryNotice == BatteryNotice.LOW |
      api_batteryIn.confidence == BatteryConfidence.TRUSTED &
        api_batteryIn.band == BatteryBand.CRITICAL &
        api_pilotStatusOut.batteryNotice == BatteryNotice.CRITICAL

  /** Compute Entrypoint Contract
    *
    * guarantee FLIGHT_INTENT_DERIVATION
    * @param api_resolutionIn incoming data port
    * @param api_flightControlOut outgoing data port
    */
  @strictpure def compute_spec_FLIGHT_INTENT_DERIVATION_guarantee(
      api_resolutionIn: Drone_Lifecycle_Energy_Governor.LifecycleResolution,
      api_flightControlOut: Drone_Lifecycle_Energy_Governor.FlightControlOutputs): B =
    api_resolutionIn.nextPhase == LifecyclePhase.FLYING &
      api_resolutionIn.sourceLifecycleState != SourceLifecyclePhase.FLYING &
      api_flightControlOut.intent == FlightIntent.LAUNCH |
      api_resolutionIn.nextPhase == LifecyclePhase.FLYING &
        api_resolutionIn.sourceLifecycleState == SourceLifecyclePhase.FLYING &
        api_flightControlOut.intent == FlightIntent.CONTINUE |
      api_resolutionIn.nextPhase == LifecyclePhase.RETURNING &
        api_flightControlOut.intent == FlightIntent.RETURN |
      api_resolutionIn.nextPhase == LifecyclePhase.LANDING &
        api_flightControlOut.intent == FlightIntent.LAND |
      (api_resolutionIn.nextPhase == LifecyclePhase.OFF |
        api_resolutionIn.nextPhase == LifecyclePhase.STANDBY |
        api_resolutionIn.nextPhase == LifecyclePhase.CHARGING |
        api_resolutionIn.nextPhase == LifecyclePhase.READY) &
        api_flightControlOut.intent == FlightIntent.HOLD

  /** Compute Entrypoint Contract
    *
    * guarantee PERMISSION_DERIVATION
    * @param api_resolutionIn incoming data port
    * @param api_chargePermissionOut outgoing data port
    * @param api_flightControlOut outgoing data port
    * @param api_propulsionPermissionOut outgoing data port
    */
  @strictpure def compute_spec_PERMISSION_DERIVATION_guarantee(
      api_resolutionIn: Drone_Lifecycle_Energy_Governor.LifecycleResolution,
      api_chargePermissionOut: Drone_Lifecycle_Energy_Governor.ChargePermission.Type,
      api_flightControlOut: Drone_Lifecycle_Energy_Governor.FlightControlOutputs,
      api_propulsionPermissionOut: Drone_Lifecycle_Energy_Governor.PropulsionPermission.Type): B =
    api_chargePermissionOut == ChargePermission.PERMITTED == (api_resolutionIn.nextPhase == LifecyclePhase.CHARGING &
       api_resolutionIn.chargeRetentionEligible) &
      api_flightControlOut.launchPermission == LaunchPermission.PERMITTED == (api_resolutionIn.nextPhase == LifecyclePhase.READY &
        api_resolutionIn.launchReady) &
      api_propulsionPermissionOut == PropulsionPermission.ENABLED == (api_flightControlOut.intent != FlightIntent.HOLD)

  /** Compute Entrypoint Contract
    *
    * guarantee ATOMIC_PHASE_AND_FAULT_COPY
    * @param api_faultsIn incoming data port
    * @param api_resolutionIn incoming data port
    * @param api_pilotStatusOut outgoing data port
    */
  @strictpure def compute_spec_ATOMIC_PHASE_AND_FAULT_COPY_guarantee(
      api_faultsIn: Drone_Lifecycle_Energy_Governor.FaultVector,
      api_resolutionIn: Drone_Lifecycle_Energy_Governor.LifecycleResolution,
      api_pilotStatusOut: Drone_Lifecycle_Energy_Governor.PilotStatus): B =
    (api_resolutionIn.nextPhase == LifecyclePhase.OFF &
       api_pilotStatusOut.phase == PublishedPhase.OFF |
       api_resolutionIn.nextPhase == LifecyclePhase.STANDBY &
         api_pilotStatusOut.phase == PublishedPhase.STANDBY |
       api_resolutionIn.nextPhase == LifecyclePhase.CHARGING &
         api_pilotStatusOut.phase == PublishedPhase.CHARGING |
       api_resolutionIn.nextPhase == LifecyclePhase.READY &
         api_pilotStatusOut.phase == PublishedPhase.READY |
       api_resolutionIn.nextPhase == LifecyclePhase.FLYING &
         api_pilotStatusOut.phase == PublishedPhase.FLYING |
       api_resolutionIn.nextPhase == LifecyclePhase.RETURNING &
         api_pilotStatusOut.phase == PublishedPhase.RETURNING |
       api_resolutionIn.nextPhase == LifecyclePhase.LANDING &
         api_pilotStatusOut.phase == PublishedPhase.LANDING) &
      api_pilotStatusOut.batteryFault == api_faultsIn.batteryFault &
      api_pilotStatusOut.chargerFault == api_faultsIn.chargerFault &
      api_pilotStatusOut.navigationFault == api_faultsIn.navigationFault &
      api_pilotStatusOut.flightControlFault == api_faultsIn.flightControlFault &
      api_pilotStatusOut.homeFault == api_faultsIn.homeFault &
      api_pilotStatusOut.touchdownFault == api_faultsIn.touchdownFault &
      api_pilotStatusOut.aggregateFault == api_faultsIn.aggregateFault

  /** CEP-T-Guar: Top-level guarantee contracts for outcomeCompositionOwner's compute entrypoint
    *
    * @param api_batteryIn incoming data port
    * @param api_faultsIn incoming data port
    * @param api_resolutionIn incoming data port
