    */
  @strictpure def compute_CEP_T_Guar (
      api_batteryIn: Drone_Lifecycle_Energy_Governor.BatteryStateFacts,
      api_faultsIn: Drone_Lifecycle_Energy_Governor.FaultVector,
      api_resolutionIn: Drone_Lifecycle_Energy_Governor.LifecycleResolution,
      api_chargePermissionOut: Drone_Lifecycle_Energy_Governor.ChargePermission.Type,
      api_flightControlOut: Drone_Lifecycle_Energy_Governor.FlightControlOutputs,
      api_pilotStatusOut: Drone_Lifecycle_Energy_Governor.PilotStatus,
      api_propulsionPermissionOut: Drone_Lifecycle_Energy_Governor.PropulsionPermission.Type): B =
    {
      val r0 = compute_spec_REQUEST_RESULT_DERIVATION_guarantee(api_resolutionIn, api_pilotStatusOut)
      val r1 = compute_spec_BATTERY_NOTICE_DERIVATION_guarantee(api_batteryIn, api_pilotStatusOut)
      val r2 = compute_spec_FLIGHT_INTENT_DERIVATION_guarantee(api_resolutionIn, api_flightControlOut)
      val r3 = compute_spec_PERMISSION_DERIVATION_guarantee(api_resolutionIn, api_chargePermissionOut, api_flightControlOut, api_propulsionPermissionOut)
      val r4 = compute_spec_ATOMIC_PHASE_AND_FAULT_COPY_guarantee(api_faultsIn, api_resolutionIn, api_pilotStatusOut)

      r0 & r1 & r2 & r3 & r4
    }

